sys_variable_value.value:
(function execute(inputs, outputs) {

    try {
        var parsed = JSON.parse(inputs.raw_response || "{}");
        var text = parsed.model_output || "";

        // Stock Price
        var stockMatch = text.match(/Stock Price:\s*(.*)/);
        outputs.stockprice = stockMatch ? stockMatch[1].trim() : "";

        // Summary
        var summaryMatch = text.match(/Summary:\s*([\s\S]*?)Risk Level:/);
        outputs.summary = summaryMatch ? summaryMatch[1].trim() : "";

        // Risk Level
        var riskMatch = text.match(/Risk Level:\s*(.*)/);
        outputs.risklevel = riskMatch ? riskMatch[1].trim() : "";

        // News (multiline)
        var newsMatch = text.match(/News:\s*([\s\S]*?)Summary:/);
        outputs.news = newsMatch ? newsMatch[1].trim() : "";

    } catch (e) {

        outputs.stockprice = "Error";
        outputs.news = "Error";
        outputs.summary = "Error";
        outputs.risklevel = "Error";

    }

})(inputs, outputs);

